tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets ln -s '$name' name.dat && ln -s '$count' count.dat && ## mothur names the per-group files after the *extension of the input file*, ## so pin it to .fasta to keep the output names stable ln -s '$fasta' fasta.fasta && ln -s '$group' group.dat &&
echo 'split.groups( #if $name: name=name.dat, #end if #if $groups: groups=${ str($groups).replace(",","-") }, #end if #if $count: count=count.dat, #end if fasta=fasta.fasta, group=group.dat )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | mothur | tee mothur.out.log
